VAR
    Overload_Timer : TON;
END_VAR

// Calculate thresholds
// 110% of 41.5A = 45.65A
// 125% of 41.5A = 51.875A

// Safe Mode and Alarm Logic
IF Motor_Current >= 45.65 THEN
    Safe_Mode_Active := TRUE;
    Overload_Alarm := TRUE;
ELSIF Fault_Reset THEN
    Safe_Mode_Active := FALSE;
    Overload_Alarm := FALSE;
END_IF;

// Shutdown Logic
Overload_Timer(IN := (Motor_Current >= 51.875 AND Motor_Running), PT := T#3S);

IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF;

IF Fault_Reset THEN
    Motor_Stop := FALSE;
END_IF;

